        'perm.email:admin.label': 'Manage email',
        'perm.email:admin.description': 'Configure and administer the email/mail-server subsystem.',
        'perm.email:provider.label': 'Send email as provider (administrator-level)',
        'perm.email:provider.description': 'Act as the site\'s outbound email provider: it sends, and can read, every message the site sends through it. If you also let it carry password-reset and verification email (Settings → Account email), it receives those links and can take over any account, administrators included — treat this grant like making the plugin an administrator.',
        'perm.smtp:inbound.label': 'Receive internet email (port 25)',
        'perm.smtp:inbound.description': 'WordJS opens the public SMTP port 25 for this plugin and hands it every email that arrives from the internet. Only ONE plugin can hold this permission at a time: revoke it from the current holder first.',
        'perm.notifications:send.label': 'Send notifications',
        'perm.notifications:send.description': 'Emit in-app notifications to admins.',
        'perm.notifications:provider.label': 'Notifications provider (administrator-level)',
        'perm.notifications:provider.description': 'Act as the site\'s notification delivery backend. It receives the full, unredacted content of every notification it delivers — including the sign-in codes and links other plugins send — so treat this grant like making the plugin an administrator.',
        'perm.express:register_route.label': 'Register API routes',
        'perm.express:register_route.description': 'Add its own HTTP endpoints under the API. Runs in the plugin sandbox.',
        'perm.admin_menu:register.label': 'Add admin menu',
        'perm.admin_menu:register.description': 'Add its own item(s) to the admin sidebar.',
        'perm.assets:write.label': 'Add scripts and styles to public pages',
        'perm.assets:write.description': 'Load a JavaScript or CSS file from its own plugin directory onto your public pages. The script runs in every visitor\'s browser, with access to whatever they can see or type on the page. The host checks the file is inside the plugin\'s directory and emits the tag itself — the plugin cannot inject raw HTML — but the code it points at is the plugin\'s own.',
        'perm.browser:script.label': 'Run code in your browser',
        'perm.browser:script.description': 'Runs code in your browser with your administrator session. Its admin page, admin extensions and editor blocks are loaded into this admin app itself, so that code can do anything you can do here — create users, change roles, install plugins. It is not sandboxed and not scanned. Grant only if you trust this plugin as much as an administrator account.',
        'plugins.notGranted.title': 'This plugin\'s interface is not loaded',
        'plugins.notGranted.body': 'This plugin\'s interface is not served until you grant \'Run code in your browser\' ({permission}) in Admin → Plugins → Permissions.',
        'plugins.notGranted.trust': 'That permission runs the plugin\'s code in this admin app with the session of whoever opens it. Grant it only if you trust {plugin} as much as an administrator account. Only an administrator can grant it.',
        'plugins.notGranted.open': 'Open the permissions of {plugin}',
        'plugins.notGranted.unavailable.title': 'This screen is not available',
        'plugins.notGranted.unavailable.body': 'An administrator has not enabled this plugin\'s interface yet. Ask an administrator to enable it.',
        'perm.roles:declare.label': 'Register its own user roles',
        'perm.roles:declare.description': 'Add the user roles listed below, so you can give someone access to this plugin\'s screens and nothing else. Such a role can only ever hold this plugin\'s own permissions, plus entering the admin panel and the user\'s own account page — the platform refuses anything else, so it can never reach your content, users, settings or another plugin. You choose who holds it, in Users; if some users already hold it, how many is shown next to the role.',
        'perm.posts:read.label': 'Read all posts',
        'perm.posts:read.description': 'Receive every post and page as it is created, updated or deleted — including drafts, private and scheduled content (never post passwords).',
        'perm.comments:read.label': 'Read comments',
        'perm.comments:read.description': 'Receive every comment as it is submitted or deleted, including unapproved ones, and veto comments before they are saved (anti-spam). The commenter\'s email, IP address and browser are withheld.',
        'perm.comments:pii.label': 'See commenters\' personal data',
        'perm.comments:pii.description': 'Also receive each commenter\'s email address, IP address and browser user agent with comment events. Needed by anti-spam services; this is personal data of your visitors.',
        'perm.notifications:read.label': 'Read notifications',
        'perm.notifications:read.description': 'Receive a copy of every in-app notification sent to any user. Reset codes, tokens and verification links are redacted.',
        'perm.media:private_read.label': 'Deliver private media files',
        'perm.media:private_read.description': 'Read the description of PRIVATE media-library files and send their contents as the response of the plugin\'s own routes. The plugin decides who receives a private file (for example, a buyer holding a paid download link), so grant it only to a plugin you trust to keep those files private.',
