        'perm.users:read.label': 'Ler usuários',
        'perm.users:read.description': 'Ver uma visão limitada das contas de usuário (sem senhas nem segredos).',
        'perm.email:admin.label': 'Administrar o e-mail',
        'perm.email:admin.description': 'Configurar e administrar o e-mail e o servidor de e-mail.',
        'perm.email:provider.label': 'Enviar e-mail como provedor (nível administrador)',
        'perm.email:provider.description': 'Atuar como o provedor de e-mail de saída do site: envia, e pode ler, cada mensagem que o site manda por ele. Se você também deixar que ele leve os e-mails de redefinição de senha e de verificação (Configurações → E-mail da conta), ele recebe esses links e pode assumir qualquer conta, inclusive as de administração: trate esta permissão como tornar o plugin administrador.',
        'perm.smtp:inbound.label': 'Receber e-mail da internet (porta 25)',
        'perm.smtp:inbound.description': 'O WordJS abre a porta SMTP 25 para este plugin e entrega a ele todo e-mail que chega da internet. Apenas um plugin pode ter esta permissão por vez: revogue-a primeiro de quem a tiver.',
        'perm.notifications:send.label': 'Enviar notificações',
        'perm.notifications:send.description': 'Enviar notificações dentro do painel para os administradores.',
        'perm.notifications:provider.label': 'Provedor de notificações (nível administrador)',
        'perm.notifications:provider.description': 'Atuar como o sistema que entrega as notificações do site. Recebe o conteúdo completo, sem ocultar nada, de cada notificação que entrega — incluindo os códigos e links de acesso que outros plugins enviam —, então trate esta permissão como tornar o plugin administrador.',
        'perm.express:register_route.label': 'Registrar rotas da API',
        'perm.express:register_route.description': 'Adicionar os seus próprios endpoints HTTP sob a API. São executados no ambiente isolado do plugin.',
        'perm.admin_menu:register.label': 'Adicionar ao menu de administração',
        'perm.admin_menu:register.description': 'Adicionar os seus próprios itens à barra lateral de administração.',
        'perm.assets:write.label': 'Adicionar scripts e estilos às páginas públicas',
        'perm.assets:write.description': 'Carregar um arquivo JavaScript ou CSS do seu próprio diretório nas suas páginas públicas. O script é executado no navegador de cada visitante, com acesso a tudo o que ele vê ou digita na página. O WordJS verifica que o arquivo está dentro do diretório do plugin e escreve a tag ele mesmo (o plugin não pode injetar HTML), mas o código para o qual aponta é do plugin.',
        'perm.browser:script.label': 'Executar código no seu navegador',
        'perm.browser:script.description': 'Executa código no seu navegador com a sua sessão de administrador. A página de administração, as extensões e os blocos do editor são carregados dentro deste mesmo painel, então esse código pode fazer tudo o que você pode fazer aqui: criar usuários, mudar funções, instalar plugins. Não é isolado nem analisado. Conceda apenas se confiar neste plugin tanto quanto em uma conta de administrador.',
        'plugins.notGranted.title': 'A interface deste plugin não está carregada',
        'plugins.notGranted.body': 'A interface deste plugin não é servida até você conceder «Executar código no seu navegador» ({permission}) em Plugins → Permissões.',
        'plugins.notGranted.trust': 'Essa permissão executa o código do plugin neste painel com a sessão de quem o abrir. Conceda-a apenas se você confiar em {plugin} tanto quanto em uma conta de administrador. Só um administrador pode concedê-la.',
        'plugins.notGranted.open': 'Abrir as permissões de {plugin}',
        'plugins.notGranted.unavailable.title': 'Esta tela não está disponível',
        'plugins.notGranted.unavailable.body': 'Um administrador ainda não habilitou a interface deste plugin. Peça a um administrador que a habilite.',
        'perm.roles:declare.label': 'Registrar as suas próprias funções de usuário',
        'perm.roles:declare.description': 'Adiciona as funções de usuário listadas abaixo, para que você possa dar a alguém acesso às telas deste plugin e a nada mais. Uma função assim só pode ter as permissões próprias deste plugin, além de entrar no painel de administração e na página da própria conta: a plataforma recusa qualquer outra coisa, então ela nunca alcança o seu conteúdo, os seus usuários, as suas configurações nem outro plugin. Você escolhe quem a tem, em Usuários; se alguns usuários já a têm, junto à função aparece quantos.',
        'perm.posts:read.label': 'Ler todas as publicações',
        'perm.posts:read.description': 'Receber cada publicação e página quando é criada, atualizada ou excluída — incluindo rascunhos e conteúdo privado e agendado (nunca as senhas das publicações).',
        'perm.comments:read.label': 'Ler comentários',
        'perm.comments:read.description': 'Receber cada comentário quando é enviado ou excluído, incluindo os não aprovados, e vetar comentários antes de serem salvos (antispam). O e-mail, o endereço IP e o navegador de quem comenta são retidos.',
